// std::auto_ptr: Ownership Transfer on Copy/Assignment (DEPRECATED)

std::auto_ptr<int> ptrA(new int(42));

// Assignment transfers ownership
std::auto_ptr<int> ptrB;
ptrB = ptrA; 

// After transfer: ptrA loses ownership (is null)
// ptrA.get() == nullptr

// Copy initialization also transfers ownership
std::auto_ptr<int> ptrC = ptrB;
// ptrB.get() == nullptr
// *ptrC == 42

// DANGER: Copy operations modify the source (unlike modern smart pointers)
